pub trait SmeltPropertyKey {
    fn smelt_array_index(&self) -> Option<u32>;
    fn smelt_key_hash(&self) -> u64;
    fn smelt_key_fingerprint(&self) -> u32;
    fn smelt_is_internal_key(&self) -> bool;
}

